par.button:
@Command([EditDocument]; "1");

@If(Changes="";@Return(@Do(@Command([EditGotoField];"Changes");@Prompt([Ok];"Missing Value";"Please select the changes option")));"");

log :=  	@Implode(Changes;" & ") + " - Submitted by : " + @Text(@Name([CN];@UserName)) + " on " + @Text(@Date(@Today)) + @NewLine;

FIELD SentBy := @V3UserName;
FIELD SentDate := @Today ;
FIELD HistoryLog := log + @NewLine + HistoryLog;

@MailSend(HR;HRMgr;NULL;@DbTitle+" - Changes : "+Changes;NULL;"Please follow this doclink  ------>";[IncludeDoclink]);

@Command([ViewRefreshFields]);
@PostedCommand([FileSave]);
@Command([FileCloseWindow])Notify HR

code.formula:
@Command([EditDocument];"1");

@If(coname="";@Return(@Do(@Command([EditGotoField];"coname");@Prompt([Ok];"Alert!";"Please select the company name before proceeding!")));"");

@If(div ="";@Return(@Do(@Command([EditGotoField];"div");@Prompt([Ok];"Alert!";"Please select the division before proceeding!")));"");

@If(dept ="";@Return(@Do(@Command([EditGotoField];"dept");@Prompt([Ok];"Alert!";"Please select the dept before proceeding!")));"");

@If(sect ="";@Return(@Do(@Command([EditGotoField];"sect");@Prompt([Ok];"Alert!";"Please select the section before proceeding!")));"");

@If(pic  ="";@Return(@Do(@Command([EditGotoField];"pic");@Prompt([Ok];"Alert!";"Please enter the person in charge before proceeding!")));"");

@If(jobtitle ="";@Return(@Do(@Command([EditGotoField];"jobtitle");@Prompt([Ok];"Alert!";"Please enter the job title before proceeding!")));"");

@If(repno ="";@Return(@Do(@Command([EditGotoField];"repno");@Prompt([Ok];"Alert!";"Please enter the information in Report to before proceeding!")));"");

@If(desg_1 ="";@Return(@Do(@Command([EditGotoField];"desg_1");@Prompt([Ok];"Alert!";"Please enter the designation before proceeding!")));"");

@If(appname ="";@Return(@Do(@Command([EditGotoField];"appname");@Prompt([Ok];"Alert!";"Please select the approval party before proceeding!")));"");

@If(desg_2 ="";@Return(@Do(@Command([EditGotoField];"desg_2");@Prompt([Ok];"Alert!";"Please enter the designation of your superior before proceeding!")));"");


FIELD CurrentAction :="Submitted";
FIELD dateapp1:= @Today;
FIELD status := "0";
FIELD CDate :=@Created;

@SetField("RemApp1Date";@Adjust(dateapp1;0;0;7;0;0;0));

@MailSend(appname;NULL;NULL;"New Job Description :  " + jobno;NULL;"Please follow this doclink to endorse the Job Description ---> ";[IncludeDoclink]);

@Command([FileCloseWindow])

@Command([EditDocument];"1");
FIELD Status:="Approved";
FIELD  dateapp2:= @Today;
FIELD CurrentAction :="Approved";
@Command([FileSave]);
@MailSend(endname;Creator:HR;NULL;"New Job Description :  " +@Trim( jobno) + " : (Approved) " ; NULL;"Please follow this doclink to endorse the Job Description ---> ";[IncludeDoclink]);
@Command([ViewRefreshFields]);
@PostedCommand([FileSave]);
@Command([FileCloseWindow])

@Command([EditDocument];"1");
FIELD Status:="RejHOD";
FIELD DateRej2 :=@Today;
FIELD CurrentAction :="Rejected";
FIELD HODStatus :="Rejected";
FIELD HOD :=@Name([CN];@UserName);


@SetField("RemRejIni1Date";@Adjust(DateRej2;0;0;15;0;0;0));
@SetField("ObsDate";@Adjust(DateRej2;0;0;30;0;0;0));

@DialogBox("EnterCommentsHOD"; [AutoVertFit] : [AutoHorzFit]);
@Command([FileSave]);
@MailSend(byname;HRMail;NULL;"New Job Description :  " +@Trim( jobno) + " : (Rejected) " ; NULL;"Please follow this doclink to the denied Job Description --->  ";[IncludeDoclink]);
@Command([ViewRefreshFields]);
@PostedCommand([FileSave]);
@Command([FileCloseWindow])

@Command([EditDocument];"1");
