@SetField ("effecdate";"dateapp3");
@Command([FileSave]);
@MailSend(Initiator;appname:HR;NULL;"New Job Description :  " +@Trim( jobno); NULL;"Please follow this doclink to the endorsed Job Description --> ";[IncludeDoclink]);
@Command([FileCloseWindow])

@Command([EditDocument];"1");
